#!/usr/bin/env node
// Materialise authored question families into static JSON; no generation at runtime.
// Each family supplies its own worked solution, two hints, and misconception.
const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const seed = JSON.parse(fs.readFileSync(path.join(root, 'data/seed-questions.json'), 'utf8'));
const bank = [];
const families = { walk: {}, desk: {} };
const n = value => String(Number(Number(value).toFixed(4)));
const gcd = (a, b) => b ? gcd(b, a % b) : Math.abs(a);
const fraction = (a, b) => { const g = gcd(a, b); return `${a / g}/${b / g}`; };
function family(mode, topic, skill, values, make) {
  (families[mode][topic] ??= []).push(values.map((v, i) => ({ mode, topic, subtopic: skill, difficulty: [1, 2, 3][i % 3], ...make(v, i) })));
}
function item(question, answer, explanation, hints, pitfall, extra = {}) {
  return { question, answer: typeof answer === 'number' ? n(answer) : String(answer), explanation, hints, pitfall, ...extra };
}
const rect = (w, h, unit = 'cm') => ({ type: 'rectangle', width: `${w} ${unit}`, height: `${h} ${unit}`, description: `Rectangle with length ${w} ${unit} and width ${h} ${unit}.` });
const lshape = (w,h,cw,ch) => ({ type: 'l_shape', width: `${w} m`, height: `${h} m`, cutWidth: `${cw} m`, cutHeight: `${ch} m`, description: `${w} m by ${h} m rectangle with a ${cw} m by ${ch} m corner removed.` });
const grid = points => ({ type: 'coordinates', points, description: points.map(p => `${p.label} is at (${p.x}, ${p.y})`).join('; ') + '. Each grid step is one unit.' });

family('walk','number_operations','multiplication_strategies',[18,24,36], a => item(`Work out ${a} × 5.`,a*5,`Multiplying by 5 is the same as multiplying by 10 and halving: ${a} × 10 = ${a*10}, then halve to get ${a*5}. Check by adding ${a} five times.`,['How could multiplying by 10 help?','Find ten times the number, then halve that result.'],'Do not halve the original number without also multiplying by 10.'));
family('walk','number_operations','order_operations',[6,8,9], a => item(`Work out ${a} + 4 × 3.`,a+12,`Multiplication comes before addition, so first work out 4 × 3 = 12. Now add ${a}: ${a} + 12 = ${a+12}. You can check by grouping the four threes.`,['Which operation takes priority?','Work out 4 × 3 before doing the addition.'],'Adding first would change the expression; there are no brackets around the addition.'));
family('walk','number_operations','factors',[18,24,30], a => item(`What is the largest factor of ${a} that is smaller than ${a}?`,a/2,`The largest proper factor of an even number is half the number. ${a} ÷ 2 = ${a/2}, and ${a/2} × 2 = ${a}. Any larger factor would need a multiplier between 1 and 2.`,['A factor must divide the number exactly.','Try pairing the number with its smallest factor greater than 1.'],'The number itself is a factor, but the question asks for a smaller one.'));
family('walk','number_operations','estimation',[39,59,79], a => item(`Round ${a} to the nearest ten, then multiply your rounded number by 6.`,Math.round(a/10)*60,`${a} rounds to ${Math.round(a/10)*10} because the units digit is 9. Multiplying the rounded number by 6 gives ${Math.round(a/10)*60}. This is an estimate, so it is larger than the exact product.`,['What are the two nearest multiples of ten?','A units digit of 9 rounds up to the next ten.'],'Use the rounded number, rather than calculating the exact product.'));
family('desk','number_operations','order_operations',[[18,6,4],[24,8,4],[30,10,5]],([a,b,c])=>item(`Work out (${a} + ${b}) ÷ ${c} + 7.`,(a+b)/c+7,`Start inside the brackets: ${a} + ${b} = ${a+b}. Divide by ${c} to get ${(a+b)/c}, then add 7 to get ${(a+b)/c+7}. The brackets must be completed before division.`,['What do the brackets tell you to do first?',`First calculate ${a} + ${b}; then divide that total by ${c}.`],'Do not add 7 to the divisor; it is a separate operation.'));
family('desk','number_operations','multi_step_cost',[[7,24,9],[8,18,12],[9,16,12]],([packs,per,used])=>item(`A club buys ${packs} packs of ${per} pencils. It gives ${used} pencils to each of 10 classes. How many pencils remain?`,packs*per-used*10,`First calculate the number bought: ${packs} × ${per} = ${packs*per}. The classes receive ${used} × 10 = ${used*10} pencils. Subtract to find ${packs*per-used*10} left. Check by adding the used and remaining pencils.`,['Find the total bought and the total given away separately.',`There are ${packs} × ${per} pencils at the start; ${used} × 10 are used.`],'Subtract the number of pencils given away, not the number of classes.'));
family('desk','number_operations','multiplication_strategies',[[28,15],[36,25],[48,35]],([a,b])=>item(`A theatre has ${a} rows with ${b} seats in each row. How many seats are there altogether?`,a*b,`There are ${a} equal groups of ${b}, so multiply ${a} × ${b} = ${a*b}. Split the multiplication into tens and units if helpful. Check that the total is larger than the seats in one row.`,['Are the equal groups added or multiplied?',`Split ${b} into tens and units, multiply each part by ${a}, then add.`],'Adding the number of rows and seats per row does not give the total seats.'));

family('walk','fractions','fraction_of_amount',[[3,4,80],[2,5,60],[5,8,64]],([a,b,total])=>item(`What is ${a}/${b} of ${total}?`,a*total/b,`Divide ${total} by ${b} to find one equal part: ${total/b}. Take ${a} parts, so ${a} × ${total/b} = ${a*total/b}. The fraction is less than one, so the answer must be smaller than ${total}.`,['Find one part before finding several parts.',`Divide ${total} by the denominator, ${b}, then multiply by ${a}.`],'Divide by the denominator before multiplying by the numerator.'));
family('walk','fractions','fraction_multiplication',[[1,2,2,3],[2,3,3,4],[3,5,5,6]],([a,b,c,d])=>item(`What is ${a}/${b} × ${c}/${d}? Give the fraction in simplest form.`,fraction(a*c,b*d),`Multiply numerators and denominators: ${a*c}/${b*d}. Simplifying gives ${fraction(a*c,b*d)}. You can also cancel common factors before multiplying to keep the numbers small. Multiplying two proper fractions gives a smaller value than either factor.`,['Could you cancel any common factors before multiplying?','Multiply the two numerators and the two denominators, then simplify.'],'Fractions are multiplied across; you do not need to add their denominators.',{ wrong_answers:['1/5','2/5','3/4','5/6'] }));
family('walk','fractions','fraction_equivalence',[[1,3,12],[2,5,20],[3,4,28]],([a,b,d])=>item(`Complete the equivalent fraction: ${a}/${b} = ?/${d}.`,a*d/b,`The denominator changes from ${b} to ${d}, a multiplication by ${d/b}. Multiply the numerator by the same factor: ${a} × ${d/b} = ${a*d/b}. Both fractions describe the same proportion.`,['What multiplication changes one denominator to the other?',`Multiply both the numerator and denominator by ${d/b}.`],'Changing only the denominator changes the value of the fraction.'));
family('walk','fractions','fraction_addition',[[1,5,2],[2,7,3],[3,8,4]],([a,b,c])=>item(`What is ${a}/${b} + ${c}/${b}? Give the fraction in simplest form.`,fraction(a+c,b),`Both fractions use ${b} equal parts, so add their numerators: ${a} + ${c} = ${a+c}. Keep the denominator ${b}, giving ${fraction(a+c,b)} in simplest form. The size of each part has not changed.`,['Are the pieces the same size?','Keep the common denominator and add the numerators.'],'Do not add the denominators when the parts have the same size.',{wrong_answers:['1/2','1/3','2/3','1/4']}));
family('desk','fractions','fraction_of_amount',[[3,5,80,4],[2,3,90,5],[3,4,120,3]],([a,b,total,c])=>item(`A box contains ${total} cards. ${a}/${b} are blue. Of the cards that are not blue, 1/${c} are red. How many are red?`,(total-a*total/b)/c,`Blue cards: ${total} ÷ ${b} × ${a} = ${a*total/b}. That leaves ${total-a*total/b} non-blue cards. Divide this remainder by ${c} to find ${(total-a*total/b)/c} red cards. The second fraction applies to the remainder, not the original total.`,['First find how many cards are not blue.',`Subtract ${a}/${b} of ${total}, then find 1/${c} of what remains.`],'The second fraction is of the remaining cards, not all the cards.'));
family('desk','fractions','fraction_equivalence',[[3,7,56],[5,6,48],[7,9,72]],([a,b,d])=>item(`Find the missing numerator: ${a}/${b} = ?/${d}.`,a*d/b,`Equivalent fractions multiply or divide both parts by the same factor. Here ${d} ÷ ${b} = ${d/b}, so multiply ${a} by ${d/b} to get ${a*d/b}. Dividing the new fraction by that factor checks the result.`,['Find the scale factor between the denominators.',`Calculate ${d} ÷ ${b}, then multiply the numerator by that factor.`],'Use the same multiplication on both parts, rather than adding the same amount.'));
family('desk','fractions','fraction_multiplication',[[3,4,2,5],[5,6,3,10],[7,8,4,7]],([a,b,c,d])=>item(`Calculate ${a}/${b} × ${c}/${d}. Give your answer as a fraction in simplest form.`,fraction(a*c,b*d),`Multiply the numerators to get ${a*c}, and the denominators to get ${b*d}. The fraction ${a*c}/${b*d} simplifies to ${fraction(a*c,b*d)}. Cancelling shared factors before multiplying gives the same simplified answer.`,['Look for common factors across a numerator and denominator.','Multiply across, then divide the top and bottom by their highest common factor.'],'The final fraction must be simplified.',{answer_format:'fraction_simplest'}));

family('walk','decimals','decimal_ordering',[[0.7,0.65,0.07,0.705,0.75],[0.4,0.39,0.405,0.45,0.04],[0.82,0.8,0.802,0.28,0.082]], values=>item(`Which is largest: ${values.join(', ')}?`,Math.max(...values),`Compare the tenths first, then hundredths, then thousandths. Add trailing zeros mentally so the places line up. The largest is ${Math.max(...values)}. More digits after a decimal point do not automatically mean a larger value.`,['Write the numbers with the same number of decimal places.','Compare from left to right, starting with tenths.'],'A decimal with more digits is not necessarily bigger.',{choices:values}));
family('walk','decimals','decimal_addition',[[1.25,0.5],[2.6,0.75],[3.45,0.8]],([a,b])=>item(`What is ${a} + ${b}?`,n(a+b),`Line up the decimal points: ${a} + ${b} = ${n(a+b)}. Adding trailing zeros can make the places easier to compare. Check by subtracting ${b} from your answer to recover ${a}.`,['Line up tenths with tenths and hundredths with hundredths.','You may add trailing zeros without changing a decimal’s value.'],'Do not line up the last digits if they represent different place values.'));
family('walk','decimals','decimal_scaling',[1.35,2.48,3.07],a=>item(`What is ${a} × 100?`,a*100,`Multiplying by 100 makes each digit worth one hundred times as much, moving it two place-value columns to the left. ${a} becomes ${a*100}. Dividing the answer by 100 checks your result.`,['How many place-value columns does multiplying by 100 change?','Each digit moves two places to the left in a place-value chart.'],'Adding two zeros to the written decimal does not multiply its value.'));
family('walk','decimals','rounding',[4.67,7.83,2.96],a=>item(`Round ${a} to one decimal place.`,n(Math.round(a*10)/10),`Look at the hundredths digit to round to tenths. It is at least 5, so increase the tenths digit, carrying if necessary. ${a} rounds to ${n(Math.round(a*10)/10)}. This is the nearest tenth.`,['One decimal place means the nearest tenth.','Use the hundredths digit to decide whether to round up.'],'Round to the requested place; do not simply delete the final digit.'));
family('desk','decimals','money_multiplication',[[3.45,8],[6.75,7],[8.95,6]],([price,count])=>item(`${count} notebooks each cost £${price.toFixed(2)}. What is the total cost in pounds?`,n(price*count),`Multiply the price of one notebook by the number bought: ${price} × ${count} = ${n(price*count)} pounds. You can work in pence and divide by 100 afterwards. Estimate first to check the decimal point.`,['Find the cost in pence if decimals feel awkward.',`${Math.round(price*100)} pence per notebook × ${count}; convert back to pounds.`],'Keep pounds and pence consistent throughout the calculation.',{unit:'£'}));
family('desk','decimals','exchange_rate',[[40,1.2],[80,1.15],[120,1.25]],([pounds,rate])=>item(`At an exchange rate of £1 = €${rate.toFixed(2)}, how many euros are received for £${pounds}?`,n(pounds*rate),`Each pound buys ${rate} euros, so multiply ${pounds} by ${rate} to get ${n(pounds*rate)} euros. The rate is greater than one, so the number of euros should exceed the number of pounds.`,['How many euros does each pound buy?',`Multiply the pounds by ${rate}; do not divide by the rate.`],'Use the rate in the direction stated in the question.',{unit:'€'}));
family('desk','decimals','money_change',[[20,2.35,4],[30,3.65,6],[50,4.85,7]],([paid,price,count])=>item(`Maya pays £${paid} for ${count} pens costing £${price.toFixed(2)} each. How much change does she receive, in pounds?`,n(paid-price*count),`First find the total cost: ${count} × £${price.toFixed(2)} = £${(price*count).toFixed(2)}. Subtract this from £${paid} to get £${(paid-price*count).toFixed(2)} change. Check that cost plus change equals the amount paid.`,['There are two calculations: total cost, then change.',`Find ${count} × ${price} before subtracting from ${paid}.`],'Subtract the total cost of all the pens, not just one pen.',{unit:'£'}));

family('walk','ratio','ratio_sharing',[[2,3,40],[3,4,56],[4,5,72]],([a,b,total])=>item(`Red and blue counters are in the ratio ${a}:${b}. There are ${total} counters. How many are blue?`,total*b/(a+b),`There are ${a+b} equal parts altogether. One part is ${total} ÷ ${a+b} = ${total/(a+b)}. Blue counters take ${b} parts, giving ${total*b/(a+b)}. The remaining red counters complete the original total.`,['Which share belongs to blue?','Add the ratio parts, find one part, then multiply by the blue share.'],'The blue share uses the second number in the ratio.'));
family('walk','ratio','unitary_method',[[3,6,5],[4,12,7],[5,15,8]],([count,cost,wanted])=>item(`${count} identical pencils cost £${cost}. How much do ${wanted} pencils cost?`,wanted*cost/count,`Find one pencil’s cost: £${cost} ÷ ${count} = £${cost/count}. Multiply by ${wanted} to find £${wanted*cost/count}. This unitary method works because every pencil has the same price.`,['Find the cost of one pencil first.',`Divide £${cost} by ${count}, then multiply by ${wanted}.`],'Do not assume the difference in counts equals the difference in price.',{unit:'£'}));
family('walk','ratio','scaling_recipe',[[2,100,6],[3,150,9],[4,200,10]],([people,grams,wanted])=>item(`A recipe for ${people} people uses ${grams} grams of rice. How many grams are needed for ${wanted} people?`,grams*wanted/people,`Each person needs ${grams} ÷ ${people} = ${grams/people} grams. For ${wanted} people, multiply by ${wanted} to get ${grams*wanted/people} grams. The ingredient amount increases in the same proportion as the people.`,['How much rice is needed for one person?',`Divide ${grams} by ${people}, then multiply by ${wanted}.`],'Scale the amount with the number of people, rather than adding their difference.',{unit:'g'}));
family('walk','ratio','ratio_difference',[[2,5,12],[3,7,20],[4,9,25]],([a,b,diff])=>item(`The ratio of small to large beads is ${a}:${b}. There are ${diff} more large beads. How many small beads are there?`,a*diff/(b-a),`The difference in ratio parts is ${b} − ${a} = ${b-a}. These parts represent ${diff} beads, so one part is ${diff/(b-a)}. The small beads occupy ${a} parts, giving ${a*diff/(b-a)}.`,['Does the given difference represent all the parts?',`Find ${b} − ${a}, then divide ${diff} by that difference.`],'Use the difference between the parts, not their sum.',{oral_load:'steps'}));
family('desk','ratio','ratio_sharing',[[3,5,96],[4,7,132],[5,8,156]],([a,b,total])=>item(`A school divides £${total} between art and sport in the ratio ${a}:${b}. How many pounds does sport receive?`,total*b/(a+b),`The total number of parts is ${a+b}. Divide £${total} by ${a+b} to find £${total/(a+b)} per part. Sport receives ${b} parts, or £${total*b/(a+b)}. Check both shares add to £${total}.`,['Which number in the ratio refers to sport?','Add the parts, divide the total by that sum, then find the sport share.'],'The order of the labels matches the order of the ratio.',{unit:'£'}));
family('desk','ratio','volume_ratio',[[8,4,5],[9,3,6],[10,5,8]],([large,small,h])=>item(`Two boxes have square bases of side ${large} cm and ${small} cm. Both are ${h} cm high. Give the large volume : small volume ratio in simplest form.`,`${large*large/(gcd(large*large,small*small))}:${small*small/(gcd(large*large,small*small))}`,`The volumes are ${large} × ${large} × ${h} = ${large*large*h} and ${small} × ${small} × ${h} = ${small*small*h} cubic centimetres. Simplify their ratio by dividing both by their highest common factor. The equal heights cancel.`,['Calculate each base area first.','The heights are equal, so comparing the square base areas also compares the volumes.'],'Changing two base dimensions changes area by the square of the side scale.',{answer_format:'ratio_simplest'}));
family('desk','ratio','unitary_method',[[6,4.8,15],[8,6.4,25],[12,9,28]],([count,cost,wanted])=>item(`${count} identical folders cost £${cost.toFixed(2)}. How much will ${wanted} folders cost, in pounds?`,n(cost/count*wanted),`One folder costs £${cost.toFixed(2)} ÷ ${count} = £${(cost/count).toFixed(2)}. Multiply this by ${wanted} to get £${(cost/count*wanted).toFixed(2)}. Check your result is proportional to the number of identical folders bought.`,['Work out the cost of a single folder first.','You may convert the cost into pence before dividing.'],'Round only if required; keep the exact unit cost for the multiplication.',{unit:'£'}));

family('walk','percentages','percent_of_amount',[[10,90],[25,80],[15,120]],([p,total])=>item(`What is ${p}% of ${total}?`,p*total/100,`A percentage is a number of hundredths. Find 10% or 1% first, then build up to ${p}%. The calculation ${total} × ${p} ÷ 100 gives ${p*total/100}. Check against a familiar fraction where possible.`,['Could you use 10%, 5% or 25% as a starting point?','Find one percent by dividing by 100, then multiply by the percentage.'],'The percent symbol means out of one hundred.'));
family('walk','percentages','percent_discount',[[20,50],[25,60],[10,80]],([p,price])=>item(`A £${price} bag has ${p}% off. What is the new price?`,price*(100-p)/100,`The discount is ${p}% of £${price}, or £${price*p/100}. Subtract this from the original price to get £${price*(100-p)/100}. The new price must be lower than the starting price.`,['Find the amount taken off before finding the new price.','Calculate the percentage of the original price, then subtract it.',],'The question asks for the price after the discount, not the discount itself.',{unit:'£'}));
family('walk','percentages','fraction_percent',[[1,2],[3,4],[2,5]],([a,b])=>item(`Write ${a}/${b} as a percentage.`,a*100/b,`A percentage compares a quantity with one hundred. Divide ${a} by ${b}, then multiply by 100 to get ${a*100/b}%. Alternatively, scale the fraction so its denominator is 100.`,['Can you make the denominator equal to 100?','Multiply the fraction by 100 to express it as a percentage.'],'A decimal and a percentage represent the same proportion on different scales.',{unit:'%'}));
family('walk','percentages','percent_increase',[[10,40],[20,60],[25,80]],([p,start])=>item(`Increase ${start} by ${p}%. What is the result?`,start*(100+p)/100,`Find ${p}% of ${start}: ${start*p/100}. Add this increase to the starting amount: ${start} + ${start*p/100} = ${start*(100+p)/100}. Since the amount increased, the result must be larger.`,['Find the increase first, then add it to the original amount.','Use 10% or 25% to help work out the percentage.'],'Do not give only the size of the increase.'));
family('desk','percentages','percent_discount',[[80,15],[120,25],[240,35]],([price,p])=>item(`A coat costs £${price}. It is reduced by ${p}%. What is its sale price in pounds?`,price*(100-p)/100,`${p}% of £${price} is £${price*p/100}. Subtract that discount from the original price: £${price} − £${price*p/100} = £${price*(100-p)/100}. Check by finding ${100-p}% of the original price instead.`,['What proportion of the original price is still paid?','Find the discount and subtract it, or calculate the remaining percentage directly.'],'Giving the discount amount answers a different question.',{unit:'£'}));
family('desk','percentages','percent_of_amount',[[240,35],[360,45],[480,65]],([total,p])=>item(`A school has ${total} pupils. ${p}% walk to school. How many pupils walk?`,total*p/100,`Find 1% of ${total} by dividing by 100, then multiply by ${p}: ${total} ÷ 100 × ${p} = ${total*p/100}. You can also split ${p}% into easier percentages and add their amounts.`,['Split the percentage into tens and fives if helpful.','Work out one percent, then multiply it by the number of percent.'],'Keep the total number of pupils as the base for the percentage.'));
family('desk','percentages','percent_increase',[[120,15],[160,25],[240,35]],([start,p])=>item(`A club has ${start} members. Membership increases by ${p}%. How many members does it have now?`,start*(100+p)/100,`The increase is ${p}% of ${start}, or ${start*p/100}. Add this to the original membership: ${start} + ${start*p/100} = ${start*(100+p)/100}. Check that the final number is above the starting membership.`,['What is the increase, rather than the final total?','Calculate the percentage increase, then add it to the starting membership.'],'The new total includes both the original members and the increase.'));

family('walk','geometry','triangle_angles',[[50,60],[45,75],[35,85]],([a,b])=>item(`A triangle has angles of ${a} and ${b} degrees. How many degrees is its third angle?`,180-a-b,`All three interior angles of a triangle add to 180 degrees. Add the two known angles: ${a} + ${b} = ${a+b}. Subtract from 180 to find ${180-a-b} degrees. Check all three add to 180.`,['What is the angle total in a triangle?','Add the known angles, then subtract the sum from 180.'],'Do not use the 360-degree angle total for a quadrilateral.',{unit:'°'}));
family('walk','geometry','perimeter',[[8,5],[11,6],[14,9]],([w,h])=>item(`A rectangle is ${w} centimetres long and ${h} centimetres wide. What is its perimeter in centimetres?`,2*(w+h),`The rectangle has two sides of ${w} cm and two of ${h} cm. Add all four sides: ${w} + ${h} + ${w} + ${h} = ${2*(w+h)} cm. Perimeter measures distance around the outside.`,['How many sides of each length are there?','Add the length and width, then double the result.'],'Multiplying length by width gives area, not perimeter.',{unit:'cm',oral_load:'visualise'}));
family('walk','geometry','rectangle_area',[[6,7],[8,9],[12,5]],([w,h])=>item(`A rectangle is ${w} centimetres by ${h} centimetres. What is its area in square centimetres?`,w*h,`Each row contains ${w} unit squares and there are ${h} rows, giving ${w} × ${h} = ${w*h} square centimetres. Area counts the squares covering a surface, rather than the length of its boundary.`,['Think about rows of unit squares covering the rectangle.','Multiply the length by the width.'],'Area uses square units; perimeter uses ordinary length units.',{unit:'cm²'}));
family('walk','geometry','angles_on_line',[65,115,135],a=>item(`Two angles make a straight line. One is ${a} degrees. How many degrees is the other?`,180-a,`Angles on a straight line add to 180 degrees. Subtract the known angle: 180 − ${a} = ${180-a} degrees. Adding the two angles checks that they form a half turn.`,['How many degrees are in a half turn?','Subtract the known angle from 180.'],'A straight line is a half turn, not a full 360-degree turn.',{unit:'°'}));
family('desk','geometry','compound_area',[[12,8,4,3],[14,9,5,4],[16,10,6,3]],([w,h,cw,ch])=>item(`Find the area of the L-shaped floor shown. It is a ${w} m by ${h} m rectangle with a ${cw} m by ${ch} m corner removed. Give square metres.`,w*h-cw*ch,`The full rectangle covers ${w} × ${h} = ${w*h} square metres. The missing corner covers ${cw} × ${ch} = ${cw*ch}. Subtract: ${w*h} − ${cw*ch} = ${w*h-cw*ch} square metres. Splitting the L into two rectangles is another valid method.`,['Could you start with the whole rectangle?','Find the area of the full rectangle and subtract the area of the missing corner.'],'Subtract areas rather than side lengths.',{unit:'m²',diagram:lshape(w,h,cw,ch)}));
family('desk','geometry','triangle_area',[[10,6],[12,7],[16,9]],([b,h])=>item(`The triangle shown has a base of ${b} cm and perpendicular height ${h} cm. What is its area in square centimetres?`,b*h/2,`A triangle is half a rectangle with the same base and perpendicular height. The rectangle would have area ${b} × ${h} = ${b*h}. Halve this to get ${b*h/2} square centimetres.`,['How is a triangle related to a rectangle with the same base and height?','Multiply the base by the perpendicular height, then halve.'],'Use perpendicular height, rather than the sloping side.',{unit:'cm²',diagram:{type:'triangle',base:`${b} cm`,height:`${h} cm`,description:`Triangle with base ${b} cm and a dashed perpendicular height of ${h} cm.`}}));
family('desk','geometry','perimeter',[[13,8],[17,9],[21,12]],([w,h])=>item(`A rectangular garden has length ${w} m and width ${h} m. A 3 m gate occupies part of the boundary. How many metres of fencing are needed for the rest?`,2*(w+h)-3,`The whole boundary is twice the length plus twice the width: 2 × (${w} + ${h}) = ${2*(w+h)} metres. Subtract the 3-metre gate, leaving ${2*(w+h)-3} metres of fencing. Check by adding the gate back.`,['Find the whole perimeter before accounting for the gate.','Double the sum of length and width, then subtract the gate’s width.'],'The gate replaces part of the fence, so its width is subtracted.',{unit:'m',diagram:rect(w,h,'m')}));

family('walk','measures','unit_conversion',[[2.5,1000,'kilograms','grams'],[1.75,1000,'litres','millilitres'],[3.2,100,'metres','centimetres']],([amount,factor,from,to])=>item(`How many ${to} are in ${amount} ${from}?`,amount*factor,`One ${from === 'kilograms' ? 'kilogram' : from === 'litres' ? 'litre' : 'metre'} contains ${factor} ${to}. Multiply ${amount} by ${factor} to get ${amount*factor} ${to}. Changing to a smaller unit increases the number because more small units cover the same amount.`,['Are you changing to a bigger unit or a smaller unit?',`There are ${factor} of the smaller units in one larger unit.`],'Multiply when converting to smaller units; the quantity itself stays the same.'));
family('walk','measures','time_duration',[[9,40,10,15],[13,35,14,20],[15,45,17,10]],([h,m,endH,endM])=>item(`How many minutes are there from ${h}:${String(m).padStart(2,'0')} to ${endH}:${String(endM).padStart(2,'0')} on the same day?`,(endH-h)*60+endM-m,`Count up to the next hour: ${60-m} minutes. Add the remaining time to ${endH}:${String(endM).padStart(2,'0')} to get ${(endH-h)*60+endM-m} minutes altogether. Hours contain 60 minutes, so ordinary decimal subtraction would not work.`,['Count up to the next full hour first.','Add the minutes before the hour to the minutes after it.'],'An hour has 60 minutes, not 100.'));
family('walk','measures','speed_distance_time',[[4,3],[5,4],[6,5]],([speed,hours])=>item(`A walker travels ${speed} kilometres each hour for ${hours} hours. How many kilometres does the walker travel?`,speed*hours,`At a steady speed, each hour adds another ${speed} kilometres. Multiply speed by time: ${speed} × ${hours} = ${speed*hours} kilometres. Dividing the distance by ${hours} checks the speed.`,['How far is travelled in each hour?','Multiply the distance per hour by the number of hours.'],'The units are already compatible, so no conversion is needed.',{unit:'km'}));
family('walk','measures','mass_difference',[[1,350],[2,750],[3,1250]],([kg,used])=>item(`A bag holds ${kg} kilograms of flour. ${used} grams are used. How many grams remain?`,kg*1000-used,`First convert ${kg} kilograms into ${kg*1000} grams. Subtract the ${used} grams used: ${kg*1000} − ${used} = ${kg*1000-used} grams. Both amounts must use the same unit before they can be subtracted.`,['Put both amounts into grams first.','Multiply the kilograms by 1000, then subtract the grams used.'],'Subtracting grams directly from kilograms mixes two different units.',{unit:'g',oral_load:'steps'}));
family('desk','measures','unit_conversion',[[450,6],[625,4],[850,8]],([grams,batches])=>item(`Each batch of a recipe uses ${grams} g of flour. How many kilograms are needed for ${batches} batches?`,grams*batches/1000,`Multiply to find the total in grams: ${grams} × ${batches} = ${grams*batches}. Divide by 1000 to convert to kilograms, giving ${grams*batches/1000} kg. Converting each batch first gives the same total.`,['Find the total mass before converting it.','Multiply grams per batch by the number of batches, then divide by 1000.'],'The final answer must be in kilograms.',{unit:'kg'}));
family('desk','measures','speed_distance_time',[[48,12],[60,15],[84,14]],([distance,speed])=>item(`A cyclist travels ${distance} km at a steady ${speed} km/h. How many minutes does the journey take?`,distance/speed*60,`Time equals distance divided by speed: ${distance} ÷ ${speed} = ${distance/speed} hours. Multiply by 60 to convert to ${distance/speed*60} minutes. Check that speed multiplied by the time in hours gives the original distance.`,['Find the journey time in hours first.','Divide distance by speed, then multiply the hours by 60.'],'The question requests minutes, even though the speed uses hours.',{unit:'minutes'}));
family('desk','measures','time_duration',[[8,45,2,35],[11,50,3,25],[14,35,2,50]],([h,m,dh,dm])=>{const end=h*60+m+dh*60+dm;return item(`A train leaves at ${h}:${String(m).padStart(2,'0')}. Its journey lasts ${dh} hours ${dm} minutes. At what time does it arrive? Use the 24-hour clock.`,`${Math.floor(end/60)}:${String(end%60).padStart(2,'0')}`,`Add the ${dh} full hours first, then add ${dm} minutes. Regroup every 60 minutes as one hour. The arrival time is ${Math.floor(end/60)}:${String(end%60).padStart(2,'0')}. Check by counting the journey duration back to departure.`,['Add the hours and minutes separately.','If the minutes reach 60, exchange 60 minutes for one hour.'],'Use 60 minutes per hour and keep the 24-hour clock format.',{answer_format:'time'});});

family('walk','algebra','number_sequences',[[4,3],[7,4],[9,5]],([start,step])=>item(`What comes next: ${start}, ${start+step}, ${start+2*step}, ${start+3*step}?`,start+4*step,`Find the difference between neighbouring terms: each step adds ${step}. Continue the pattern by adding ${step} to ${start+3*step}, giving ${start+4*step}. Check that the same rule works for all the earlier terms.`,['What changes between each pair of terms?','Work out the common difference, then add it once more.'],'Check the rule against every pair of neighbouring terms.'));
family('walk','algebra','consecutive_numbers',[36,63,96],total=>item(`Three consecutive whole numbers add to ${total}. What is the largest?`,total/3+1,`The middle number is the mean: ${total} ÷ 3 = ${total/3}. The numbers are ${total/3-1}, ${total/3}, ${total/3+1}, so the largest is ${total/3+1}. Add the three numbers to check the total.`,['The middle number is also the mean of the three.','Divide the total by three, then find the number immediately above the middle.'],'The question asks for the largest number, not the middle.'));
family('walk','algebra','function_machines',[[5,3,2],[6,4,3],[8,5,4]],([input,mult,add])=>item(`A machine multiplies a number by ${mult}, then adds ${add}. What comes out when ${input} goes in?`,input*mult+add,`Apply the rules in their stated order. First ${input} × ${mult} = ${input*mult}. Then add ${add} to get ${input*mult+add}. Reversing those operations would describe a different machine.`,['Which step does the machine perform first?','Multiply first, then add the second number.'],'The order of the machine’s steps matters.'));
family('walk','algebra','simple_equations',[[3,4,19],[4,5,29],[5,6,41]],([mult,add,total])=>item(`A number is multiplied by ${mult}, then ${add} is added. The result is ${total}. What was the number?`,(total-add)/mult,`Undo the last step first: ${total} − ${add} = ${total-add}. Divide by ${mult} to get ${(total-add)/mult}. Check by putting this number through the original multiplication and addition.`,['Work backwards from the result.','Subtract the added amount, then divide by the multiplier.'],'Reverse the order of the steps as well as reversing each operation.',{oral_load:'steps'}));
family('desk','algebra','consecutive_numbers',[135,165,195],total=>item(`Five consecutive odd numbers add to ${total}. What is the smallest?`,total/5-4,`The middle number is the mean, ${total} ÷ 5 = ${total/5}. Consecutive odd numbers differ by 2. The smallest lies two steps below the middle, so subtract 4 to get ${total/5-4}. Check all five add to ${total}.`,['For five equally spaced numbers, the mean is the middle one.','Find the mean, then move two steps of size 2 down to the smallest.'],'Consecutive odd numbers differ by two, rather than one.'));
family('desk','algebra','simple_equations',[[4,7,43],[5,9,69],[6,11,101]],([mult,add,total])=>item(`A number is multiplied by ${mult}, then ${add} is added, making ${total}. Find the original number.`,(total-add)/mult,`Work backwards using inverse operations. Subtract ${add} from ${total}, giving ${total-add}. Divide by ${mult} to get ${(total-add)/mult}. Substitute this value into the original calculation to verify the final result.`,['Which operation was performed last?','Undo the addition first, then undo the multiplication.'],'Dividing the final result before subtracting does not undo the correct steps.'));
family('desk','algebra','number_sequences',[[5,4,12],[7,5,15],[9,6,18]],([first,step,term])=>item(`A sequence begins ${first}, ${first+step}, ${first+2*step}, ${first+3*step}. The same rule continues. What is the ${term}th term?`,first+(term-1)*step,`The first term is ${first} and the common difference is ${step}. There are ${term-1} steps from the first to the ${term}th term, so calculate ${first} + ${term-1} × ${step} = ${first+(term-1)*step}.`,['How many steps separate the first term from the requested term?','Multiply the step size by one less than the term number, then add the first term.'],'The first term is already in place, so use one fewer step than the term number.'));

family('walk','statistics','mean_average',[[4,6,8],[7,9,11],[12,16,20]],values=>item(`What is the mean of ${values.join(', ')}?`,values.reduce((a,b)=>a+b)/3,`Add all three values: ${values.join(' + ')} = ${values.reduce((a,b)=>a+b)}. Divide the total by the number of values, 3, to find the mean ${values.reduce((a,b)=>a+b)/3}. It lies between the smallest and largest values.`,['The mean shares the total equally between the values.','Add the three numbers, then divide by three.'],'Divide by how many numbers there are, not by the largest number.'));
family('walk','statistics','missing_mean',[[8,6,9],[10,8,11],[12,9,13]],([mean,a,b])=>item(`Three scores have a mean of ${mean}. Two scores are ${a} and ${b}. What is the third?`,mean*3-a-b,`Mean multiplied by count gives the total: ${mean} × 3 = ${mean*3}. The known scores add to ${a+b}. Subtract to get ${mean*3-a-b}. Check that the three scores total ${mean*3}.`,['Find the total of all three scores first.','Multiply the mean by three, then subtract the two known scores.'],'The mean is not the total.',{oral_load:'steps'}));
family('walk','statistics','range',[[3,8,6],[7,15,11],[12,27,19]],values=>item(`What is the range of ${values.join(', ')}?`,Math.max(...values)-Math.min(...values),`The range is the largest value minus the smallest. Here that is ${Math.max(...values)} − ${Math.min(...values)} = ${Math.max(...values)-Math.min(...values)}. The middle value does not change the range because it is not an extreme.`,['Which is the largest value? Which is the smallest?','Subtract the smallest value from the largest.'],'Range is a difference, not the count or total of the values.'));
family('walk','statistics','data_comparison',[[12,7],[18,9],[24,15]],([a,b])=>item(`A survey finds ${a} children prefer apples and ${b} prefer pears. How many more prefer apples?`,a-b,`Compare the two counts by subtracting: ${a} − ${b} = ${a-b}. This finds the extra children in the larger group. Adding the counts would instead give the total who chose either fruit.`,['Are you finding a total or a difference?','Subtract the smaller group from the larger group.'],'“How many more” asks for a difference between counts.'));
family('desk','statistics','missing_mean',[[15,[12,16,14,18]],[20,[17,19,23,21]],[25,[20,26,28,24]]],([mean,known])=>item(`The five test scores have a mean of ${mean}. Use the table to find the missing score.`,mean*5-known.reduce((a,b)=>a+b),`The total of five scores is ${mean} × 5 = ${mean*5}. The four known scores total ${known.reduce((a,b)=>a+b)}. Subtract to find ${mean*5-known.reduce((a,b)=>a+b)} for the missing score, then check the resulting mean.`,['Find the total needed for all five scores.','Multiply the mean by five, then subtract the four scores given.'],'Include the missing score in the total number of values.',{diagram:{type:'table',caption:'Test scores',headers:['Test','Score'],rows:[...known.map((v,i)=>[String(i+1),v]),['5','?']]}}));
family('desk','statistics','data_comparison',[[8,12,16,4],[12,20,16,8],[16,24,32,12]],values=>item(`The bar chart shows books borrowed on four days (Monday: ${values[0]}). How many more books were borrowed on Wednesday than on Monday?`,values[2]-values[0],`Read the heights on the number scale, not just the number of grid lines. Wednesday shows ${values[2]} books and Monday shows ${values[0]}. Subtract: ${values[2]} − ${values[0]} = ${values[2]-values[0]} more books.`,['Check the scale on the vertical axis.','Read Wednesday and Monday, then subtract Monday’s count from Wednesday’s.'],'Each grid step may represent more than one book.',{diagram:{type:'bars',labels:['Mon','Tue','Wed','Thu'],values,max:Math.ceil(Math.max(...values)/4)*4,axis_label:'Books',description:`Books borrowed: Monday ${values[0]}, Tuesday ${values[1]}, Wednesday ${values[2]}, Thursday ${values[3]}.`},variant_key:values.join('-')}));
family('desk','statistics','line_graphs',[[8,12,20,16],[12,16,24,20],[16,20,32,24]],values=>item(`The line graph shows the temperature at four times (8 am: ${values[0]}°C). By how many degrees did it fall between noon and 2 pm?`,values[2]-values[3],`Read the temperature at noon (${values[2]}°C) and at 2 pm (${values[3]}°C). The fall is ${values[2]} − ${values[3]} = ${values[2]-values[3]} degrees. A downward segment represents a decrease, not a negative temperature.`,['Identify the two times named in the question.','Subtract the later temperature from the earlier, warmer temperature.'],'Read the axis scale carefully rather than counting the grid lines.',{unit:'°C',diagram:{type:'line',labels:['8 am','10 am','Noon','2 pm'],values,max:Math.ceil(Math.max(...values)/4)*4,axis_label:'Temperature (°C)',description:`Temperatures: 8 am ${values[0]}°C, 10 am ${values[1]}°C, noon ${values[2]}°C, 2 pm ${values[3]}°C.`},variant_key:values.join('-')}));

family('desk','statistics','pie_charts',[[80,25],[120,40],[160,35]],([total,percent])=>item(`The pie chart shows the favourite clubs of ${total} pupils. How many pupils chose art?`,total*percent/100,`The art sector represents ${percent}% of the pupils. Calculate ${percent}% of ${total}: ${total} × ${percent} ÷ 100 = ${total*percent/100}. The other sector accounts for the remaining ${100-percent}%, and both groups add to the total.`,['Read the percentage belonging to art.','Use the percentage of the whole group, rather than treating the percentage as a pupil count.'],'A percentage describes a share of the total; it is not itself the number of pupils.',{diagram:{type:'pie',labels:['Art','Sport'],values:[percent,100-percent],description:`Favourite clubs: Art ${percent}%, Sport ${100-percent}%.`}}));

family('walk','coordinates','translation',[[1,3],[2,2],[-2,5]],([x,move])=>item(`A point has x-coordinate ${x}. It moves ${move} squares right. What is its new x-coordinate?`,x+move,`Moving right increases the x-coordinate. Add the movement to the original value: ${x} + ${move} = ${x+move}. A horizontal move leaves the y-coordinate unchanged. Imagine stepping right along a number line.`,['Which coordinate changes when you move horizontally?','Moving right adds to the x-coordinate.'],'Right and left movements change x, not y.',{oral_load:'visualise'}));
family('walk','coordinates','reflection',[[2,3],[-3,2],[4,-2]],([x,y])=>item(`The point (${x}, ${y}) is reflected in the x-axis. What is its new y-coordinate?`,-y,`Reflecting in the x-axis keeps the horizontal position and reverses the vertical position. The y-coordinate changes from ${y} to ${-y}. The reflected point is the same distance on the opposite side of that axis.`,['Which coordinate measures distance above or below the x-axis?','Reflection in the x-axis changes the sign of y and keeps x unchanged.'],'Reflecting in the x-axis changes y, despite the axis being named x.',{oral_load:'visualise'}));
family('walk','coordinates','coordinate_distance',[[-2,3],[-4,2],[-3,5]],([a,b])=>item(`Two points have the same y-coordinate. Their x-coordinates are ${a} and ${b}. How many squares apart are they?`,b-a,`The points lie on the same horizontal line. Their distance is the larger x-coordinate minus the smaller: ${b} − (${a}) = ${b-a} squares. Count across zero carefully when one coordinate is negative.`,['Picture the two x-values on a number line.','Count from the negative coordinate to zero, then from zero to the positive one.'],'Distance is non-negative, even when a coordinate is negative.',{oral_load:'visualise'}));
family('walk','coordinates','coordinate_position',[[1,4],[2,5],[3,6]],([y,move])=>item(`A point has y-coordinate ${y}. It moves ${move} squares down. What is the new y-coordinate?`,y-move,`Moving down decreases the y-coordinate. Subtract the movement: ${y} − ${move} = ${y-move}. The point passes below the horizontal axis, so its new y-coordinate is negative. Its x-coordinate does not change.`,['Does moving down increase or decrease the vertical coordinate?','Subtract the downward movement from the starting y-coordinate.'],'Keep counting below zero when the movement passes the axis.',{oral_load:'visualise'}));
family('desk','coordinates','translation',[[1,2,2,-3],[-2,3,4,-2],[-3,-1,2,4]],([x,y,dx,dy])=>item(`Point P is shown on the grid. Move it ${dx} squares right and ${Math.abs(dy)} squares ${dy<0?'down':'up'}. Write the new coordinates as (x, y).`,`(${x+dx}, ${y+dy})`,`A horizontal move changes x: ${x} + ${dx} = ${x+dx}. The vertical move changes y: ${y} ${dy<0?'−':'+'} ${Math.abs(dy)} = ${y+dy}. Write x first, then y, giving (${x+dx}, ${y+dy}).`,['Read the starting coordinates in x, y order.','Add the rightward movement to x, and adjust y for the vertical movement.'],'Write the horizontal coordinate before the vertical coordinate.',{answer_format:'coordinates',diagram:grid([{x,y,label:'P'}])}));
family('desk','coordinates','reflection',[[2,3],[-3,4],[4,-2]],([x,y])=>item(`Reflect point P (${x}, ${y}) in the y-axis. Write the reflected coordinates as (x, y).`,`(${-x}, ${y})`,`Reflection in the y-axis reverses the horizontal position but leaves the vertical position unchanged. So x changes from ${x} to ${-x}, while y stays ${y}. The reflected point is (${-x}, ${y}).`,['Which axis is the mirror line?','A y-axis reflection changes the sign of x but keeps y the same.'],'Reflection in the y-axis changes x, not y.',{answer_format:'coordinates',diagram:grid([{x,y,label:'P'}]),variant_key:`${x},${y}`}));
family('desk','coordinates','rectangle_coordinates',[[-3,-2,2,3],[-4,-1,3,4],[-2,-3,4,2]],([x1,y1,x2,y2])=>item(`A (${x1}, ${y1}), B and C are three corners of rectangle ABCD, in order. Its sides follow the grid lines. Find the missing corner D and write (x, y).`,`(${x1}, ${y2})`,`Opposite sides of a rectangle are parallel and equal. D is vertically above A and horizontally level with C, so it uses A’s x-coordinate ${x1} and C’s y-coordinate ${y2}. Therefore D is (${x1}, ${y2}).`,['Which corners share a horizontal or vertical line with D?','Use the x-coordinate of A and the y-coordinate of C.'],'Keep the corner order A, B, C, D around the rectangle.',{answer_format:'coordinates',diagram:grid([{x:x1,y:y1,label:'A'},{x:x2,y:y1,label:'B'},{x:x2,y:y2,label:'C'}]),variant_key:`${x1},${y1},${x2},${y2}`}));

const seedSkills = {1:'multiplication_strategies',2:'fraction_multiplication',3:'ratio_sharing',4:'triangle_angles',5:'decimal_ordering',6:'unit_conversion',7:'consecutive_numbers',8:'estimation',9:'fraction_of_amount',10:'perimeter',121:'money_multiplication',122:'speed_distance_time',123:'compound_area',124:'fraction_equivalence',125:'volume_ratio',126:'order_operations',127:'consecutive_numbers',128:'exchange_rate',129:'unit_conversion',130:'ratio_sharing'};
const seedHints = {
  1:['Split 24 into tens and units.','Calculate 38 × 20 and 38 × 4 separately, then add.'],
  2:['Could you simplify each fraction first?','5/10 is 1/2 and 3/12 is 1/4; now multiply.'],
  3:['Which share belongs to the second charity?','There are 5 + 2 parts; divide the total by that sum first.'],
  4:['Recall the angle total for a triangle.','Add 35° and 70°, then subtract that total from 180°.'],
  5:['Write trailing zeros so every number has three decimal places.','Compare tenths first, then hundredths, then thousandths.'],
  6:['Are grams smaller or larger than kilograms?','One kilogram is 1000 grams, so multiply by 1000.'],
  7:['The middle number equals the mean.','Divide 87 by 3, then take the number just above the middle.'],
  8:['Round both factors to friendly nearby tens.','49 is near 50 and 21 is near 20; multiply those rounded values.'],
  9:['Find one eighth first.','Divide 240 by 8, then multiply that result by 3.'],
  10:['What happens to the two outside edges at the cut corner?','The new inside edges replace exactly the same lengths that were cut off.'],
  121:['Could you multiply by 10 and then subtract one ticket?','Find £7.85 × 10, then subtract £7.85.'],
  122:['Both cyclists reduce the gap each hour.','Add their speeds, divide distance by that closing speed, then convert to minutes.'],
  123:['Picture the complete rectangle before the corner was removed.','Find 10 × 6, then subtract the missing area of 4 × 3.'],
  124:['Simplify each fraction separately.','Compare every simplified fraction to 2/5.'],
  125:['Calculate each base area before comparing volumes.','Both heights are equal, so compare 6 × 6 with 3 × 3.'],
  126:['Calculate the brackets first.','Multiplication and division have equal priority; work through those from left to right.'],
  127:['The middle odd number equals the mean.','Divide 275 by 5, then subtract two steps of 2 to reach the smallest.'],
  128:['How many euros does one pound buy?','Multiply 60 by 1.15; the euro amount should be greater than 60.'],
  129:['Find the total grams for all batches first.','Multiply 750 by 3, then divide by 1000 to convert to kilograms.'],
  130:['Which share refers to blue beads?','There are 3 + 5 parts; find one part, then take five of them.'],
};
for (const q of seed) {
  q.subtopic = seedSkills[q.id]; q.hints = seedHints[q.id];
  if (q.id === 6) q.unit = 'g';
  if (q.id === 8) q.question = 'Round 49 and 21 to the nearest ten, then multiply the rounded numbers to estimate 49 × 21.';
  if (q.id === 123) q.diagram = lshape(10,6,4,3);
  q.oral_load = q.mode === 'walk' ? [1,2,3,7].includes(q.id) ? 'steps' : q.id === 10 ? 'visualise' : 'short' : null;
  bank.push(q);
}
const topics = ['number_operations','fractions','decimals','ratio','percentages','geometry','measures','algebra','statistics','coordinates'];
for (const mode of ['walk','desk']) {
  let id = mode === 'walk' ? 11 : 131;
  for (const topic of topics) {
    const needed = (mode === 'walk' ? 12 : 9) - seed.filter(q => q.mode === mode && q.topic === topic).length;
    const group = families[mode][topic];
    const pool = [0,1,2].flatMap(i => group.map(f => f[i]));
    for (const q of pool.slice(0,needed)) {
      q.id = id++; q.unit ??= null; q.answer_alt ??= null;
      q.stage = mode === 'walk' ? 'SET' : 'NWSSEE';
      q.answer = typeof q.answer === 'number' ? n(q.answer) : q.answer;
      q.time_target_seconds = mode === 'walk' ? q.oral_load === 'steps' ? 75 : 60 : 120;
      q.oral_load ??= mode === 'walk' ? 'short' : null;
      if (mode === 'walk') {
        const numeric = Number(q.answer);
        const canonical = s => {
          if (/^-?\d+\s*\/\s*\d+$/.test(s)) { const [a,b]=s.split('/').map(Number); return a/b; }
          return Number(s);
        };
        let wrong = q.choices || q.wrong_answers || (Number.isFinite(numeric) ? [numeric-1,numeric+1,numeric+2,numeric+10,numeric*2,numeric/2] : ['1/2','1/3','1/4','2/3','3/4','1/5','2/5','3/5','4/5','5/6']);
        const seen = new Set([canonical(q.answer)]);
        wrong = wrong.map(v => typeof v === 'number' ? n(v) : String(v)).filter(v => {
          const value = canonical(v);
          if (seen.has(value)) return false;
          seen.add(value); return true;
        }).slice(0,4);
        if (wrong.length !== 4) throw new Error(`Not enough distractors for ${q.question}`);
        q.answer_index = (q.id - 1) % 5; wrong.splice(q.answer_index,0,String(q.answer));
        q.options = wrong; q.answer_display = 'ABCDE'[q.answer_index];
      } else { q.options = q.answer_index = q.answer_display = null; }
      delete q.choices; delete q.wrong_answers; delete q.variant_key;
      bank.push(q);
    }
  }
}
const prompts = {
  number_operations:'Which mental or written method did you choose, and how could you check it?',
  fractions:'What does one equal part represent in this question?',
  decimals:'How does place value help you check the size of your answer?',
  ratio:'What does one ratio part stand for?',
  percentages:'Which familiar percentage or fraction could you use to check?',
  geometry:'Can you explain the shape or angle fact you used?',
  measures:'Why is that the right unit for the final answer?',
  algebra:'Does your rule work when you substitute the answer back?',
  statistics:'What does the total, comparison or average tell you about the data?',
  coordinates:'Which direction changes x, and which changes y?',
};
for (const q of bank) {
  // Multi-step warm-ups and routine third variants belong in core practice.
  const core = {
    percentages: ['walk:percent_discount:1','desk:percent_increase:1','walk:fraction_percent:3','walk:percent_of_amount:3'],
    statistics: ['walk:missing_mean:1','desk:missing_mean:1','walk:range:3','walk:data_comparison:3'],
    coordinates: ['walk:reflection:1','desk:translation:1','walk:coordinate_position:3','walk:coordinate_distance:3'],
  };
  if (core[q.topic]?.includes(`${q.mode}:${q.subtopic}:${q.difficulty}`)) q.difficulty = 2;
  q.parent_prompt = prompts[q.topic];
  q.answer = /^-?\d+(\.\d+)?$/.test(q.answer) ? n(Number(q.answer)) : q.answer;
  if (q.mode === 'walk') {
    q.spoken_question = q.question;
    if (q.answer.includes('/')) q.answer_format = 'fraction_simplest';
  }
}
bank.sort((a,b)=>a.id-b.id);
const output = JSON.stringify(bank,null,2)+'\n';
const destination = path.join(root, 'data/questions.json');
if (process.argv.includes('--check')) {
  if (fs.readFileSync(destination,'utf8') !== output) throw new Error('Question bank is out of date. Run node scripts/build-questions.cjs.');
  console.log('Question bank matches its authoring sources.');
} else {
  fs.writeFileSync(destination,output);
  console.log(`Wrote ${bank.length} questions (${bank.filter(q=>q.mode==='walk').length} walk, ${bank.filter(q=>q.mode==='desk').length} desk).`);
}
